#!/usr/bin/perl
use strict;
use warnings;
use utf8;

use Cwd qw(abs_path);
use Encode qw(decode FB_CROAK);
use Errno qw(EAGAIN EWOULDBLOCK);
use Fcntl qw(:flock F_SETFD FD_CLOEXEC O_CREAT O_NOFOLLOW O_RDWR);
use File::Basename qw(basename dirname);
use File::Path qw(make_path);
use File::Spec;
use File::Temp qw(tempfile);
use JSON::PP qw(decode_json encode_json);
use POSIX qw(strftime);
use Time::HiRes qw(sleep);

binmode STDOUT, ':encoding(UTF-8)';
binmode STDERR, ':encoding(UTF-8)';

my $DEFAULT_CONFIG = '/etc/whisper/whisper.conf';
my $MAX_ARTIFACTS = 20;
my $STATE_NAME = 'whisper-record-toggle.state';
my $LOCK_NAME = 'whisper-record-toggle.lock';
my $RECORDING_GUARD_NAME = 'whisper-record-toggle.recording';
my $RECORD_SERVICE = 'whisper-record.service';
my $TRANSCRIBE_SERVICE = 'whisper-transcribe.service';
my $SERVER_SERVICE = 'whisper-server.service';
my $SERVER_ENDPOINT = 'http://127.0.0.1:8080/inference';

sub fatal {
    my ($message) = @_;
    die "whisper-record-toggle: $message\n";
}

sub is_safe_absolute_path {
    my ($path) = @_;
    return 0 unless defined $path && length $path;
    return 0 unless File::Spec->file_name_is_absolute($path);
    return 0 if $path =~ m{\0};
    return 0 if $path =~ m{(?:\A|/)\.\.(?:/|\z)};
    return 0 if $path =~ m{//};
    return 1;
}

sub assert_safe_absolute_path {
    my ($label, $path) = @_;
    is_safe_absolute_path($path) or fatal("$label is unavailable or invalid");
    return $path;
}

sub lstat_or_fatal {
    my ($label, $path) = @_;
    my @stat = lstat $path;
    @stat or fatal("$label does not exist: $path");
    return @stat;
}

sub assert_user_owned_directory {
    my ($label, $path, $mode) = @_;
    assert_safe_absolute_path($label, $path);
    if (!-e $path) {
        make_path($path, { mode => $mode });
    }
    -d $path && !-l $path or fatal("$label must be a real directory: $path");
    my @stat = lstat_or_fatal($label, $path);
    $stat[4] == $< or fatal("$label must be owned by the active user: $path");
    chmod $mode, $path or fatal("cannot set mode on $label: $!");
    return $path;
}

sub runtime_directory {
    $< != 0 or fatal('must not run as root');
    my $runtime = $ENV{XDG_RUNTIME_DIR};
    assert_safe_absolute_path('XDG_RUNTIME_DIR', $runtime);
    -d $runtime && !-l $runtime
        or fatal('XDG_RUNTIME_DIR must be a real directory');
    my @stat = lstat_or_fatal('XDG_RUNTIME_DIR', $runtime);
    $stat[4] == $< or fatal('XDG_RUNTIME_DIR must be owned by the active user');
    ($stat[2] & 0077) == 0
        or fatal('XDG_RUNTIME_DIR must not be accessible by other users');
    return $runtime;
}

sub home_directory {
    my $home = $ENV{HOME};
    assert_safe_absolute_path('HOME', $home);
    -d $home && !-l $home or fatal('HOME must be a real directory');
    my @stat = lstat_or_fatal('HOME', $home);
    $stat[4] == $< or fatal('HOME must be owned by the active user');
    return $home;
}

sub safe_child_path {
    my ($base, $name) = @_;
    defined $name && $name !~ m{[\/\0]}
        or fatal('unsafe managed filename');
    my $path = File::Spec->catfile($base, $name);
    index($path, "$base/") == 0
        or fatal('managed path escaped its parent');
    return $path;
}

sub open_runtime_lock {
    my ($runtime, $lock_mode) = @_;
    my $path = safe_child_path($runtime, $LOCK_NAME);
    if (-e $path || -l $path) {
        !-l $path && -f $path
            or fatal("runtime lock is not a regular file: $path");
        my @stat = lstat_or_fatal('runtime lock', $path);
        $stat[4] == $< or fatal("runtime lock must be owned by the active user: $path");
    }
    sysopen my $fh, $path, O_CREAT | O_NOFOLLOW | O_RDWR, 0600
        or fatal("cannot open runtime lock: $!");
    fcntl($fh, F_SETFD, FD_CLOEXEC)
        or fatal("cannot make runtime lock close-on-exec: $!");
    flock($fh, $lock_mode)
        or fatal("cannot lock runtime state: $!");
    return $fh;
}

sub open_recording_guard {
    my ($runtime, $lock_mode) = @_;
    my $path = safe_child_path($runtime, $RECORDING_GUARD_NAME);
    if (-e $path || -l $path) {
        !-l $path && -f $path
            or fatal("recording guard is not a regular file: $path");
        my @stat = lstat_or_fatal('recording guard', $path);
        $stat[4] == $< or fatal("recording guard must be owned by the active user: $path");
    }
    sysopen my $fh, $path, O_CREAT | O_NOFOLLOW | O_RDWR, 0600
        or fatal("cannot open recording guard: $!");
    fcntl($fh, F_SETFD, 0)
        or fatal("cannot preserve recording guard across exec: $!");
    if (!flock($fh, $lock_mode)) {
        if (($lock_mode & LOCK_NB) && ($!{EAGAIN} || $!{EWOULDBLOCK})) {
            close $fh or fatal("cannot close recording guard: $!");
            return undef;
        }
        fatal("cannot lock recording guard: $!");
    }
    return $fh;
}

sub state_path {
    my ($runtime) = @_;
    return safe_child_path($runtime, $STATE_NAME);
}

sub read_raw_limited {
    my ($path, $limit) = @_;
    -f $path && !-l $path or fatal("expected regular file: $path");
    my $size = -s $path;
    defined $size && $size <= $limit
        or fatal("file is too large to parse safely: $path");
    open my $fh, '<:raw', $path
        or fatal("cannot read $path: $!");
    local $/;
    my $content = <$fh>;
    close $fh or fatal("cannot close $path: $!");
    return defined $content ? $content : q{};
}

sub read_json_object {
    my ($path, $limit, $label) = @_;
    my $raw = read_raw_limited($path, $limit);
    my $data = eval { decode_json($raw) };
    $@ and fatal("$label is not valid JSON");
    ref $data eq 'HASH' or fatal("$label must contain a JSON object");
    return $data;
}

sub atomic_write_bytes {
    my ($directory, $filename, $bytes, $mode) = @_;
    my ($fh, $temp_path) = tempfile(
        ".${filename}.tmp.XXXXXX",
        DIR    => $directory,
        UNLINK => 0,
    );
    binmode $fh, ':raw'
        or fatal("cannot configure temporary file encoding: $!");
    print {$fh} $bytes
        or fatal("cannot write temporary file: $!");
    close $fh or fatal("cannot close temporary file: $!");
    chmod $mode, $temp_path
        or fatal("cannot set temporary file mode: $!");
    my $destination = safe_child_path($directory, $filename);
    rename $temp_path, $destination
        or fatal("cannot atomically publish $destination: $!");
    return $destination;
}

sub write_state {
    my ($runtime, $state) = @_;
    atomic_write_bytes(
        $runtime,
        $STATE_NAME,
        encode_json($state) . "\n",
        0600,
    );
}

sub clear_state {
    my ($runtime) = @_;
    my $path = state_path($runtime);
    return unless -e $path;
    !-l $path && -f $path
        or fatal("runtime state is not a regular file: $path");
    my @stat = lstat_or_fatal('runtime state', $path);
    $stat[4] == $< or fatal("runtime state must be owned by the active user: $path");
    unlink $path or fatal("cannot clear runtime state: $!");
}

sub read_state {
    my ($runtime) = @_;
    my $path = state_path($runtime);
    return undef unless -e $path;
    !-l $path && -f $path
        or fatal("runtime state is not a regular file: $path");
    my @stat = lstat_or_fatal('runtime state', $path);
    $stat[4] == $< or fatal("runtime state must be owned by the active user: $path");
    my $state = read_json_object($path, 32 * 1024, 'runtime state');
    for my $key (qw(stem wav)) {
        exists $state->{$key} && defined $state->{$key}
            or fatal("runtime state is missing $key");
    }
    $state->{stem} =~ /\A[0-9]{4}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}\z/
        or fatal('runtime state contains an invalid timestamp stem');
    is_safe_absolute_path($state->{wav})
        or fatal('runtime state contains an invalid recording path');
    return $state;
}

sub resolved_recording_paths {
    my ($home) = @_;
    my $music = File::Spec->catdir($home, 'Music');
    my $whisper = File::Spec->catdir($music, 'Whisper');
    my $audio = File::Spec->catdir($whisper, 'audio');
    my $transcribed = File::Spec->catdir($whisper, 'transcribed');
    assert_user_owned_directory('Whisper audio directory', $audio, 0700);
    assert_user_owned_directory('Whisper transcription directory', $transcribed, 0700);
    return {
        audio       => $audio,
        transcribed => $transcribed,
    };
}

sub resolved_sleek_paths {
    my ($home) = @_;
    my $task_dir = File::Spec->catdir($home, 'Syncthing', 'sleek');
    assert_user_owned_directory('Sleek task directory', $task_dir, 0700);
    my $task_file = safe_child_path($task_dir, 'whisper.txt');
    if (-e $task_file) {
        !-l $task_file && -f $task_file
            or fatal("Sleek task file is not regular: $task_file");
        my @stat = lstat_or_fatal('Sleek task file', $task_file);
        $stat[4] == $< or fatal("Sleek task file must be owned by the active user");
    } else {
        atomic_write_bytes($task_dir, 'whisper.txt', q{}, 0600);
    }
