    26	sub _deb_update {
    27	    my ($self, $http, $deb, $event, $work, $app) = @_;
    28	    my $path = "$work/$app->{name}.deb";
    29	    eval {
    30	        $http->download(
    31	            label => $app->{label}, url => $app->{url}, destination => $path,
    32	            minimum => 1_048_576, maximum => $app->{maximum}, allowed_hosts => $app->{hosts},
    33	            content_policy => 'artifact',
    34	        );
    35	        my $metadata = $deb->validate(
    36	            label => $app->{label}, path => $path, packages => $app->{packages},
    37	            executable => $app->{executable}, desktop => $app->{desktop}, library => $app->{library},
    38	        );
    39	        my $installed = $deb->installed_version($metadata->{package});
    40	        if (defined $installed) {
    41	            system('/usr/bin/dpkg', '--compare-versions', $metadata->{version}, 'lt', $installed) == 0
    42	                and die "downgrade\n";
    43	            return 2 if system('/usr/bin/dpkg', '--compare-versions', $metadata->{version}, 'eq', $installed) == 0;
    44	        }
    45	        $event->emit('updating', $app->{name}, $installed // 'missing', $metadata->{version});
    46	        $deb->repository()->retain($path, $metadata);
    47	        $deb->install($path);
    48	        my $verified = $deb->installed_version($metadata->{package});
    49	        defined $verified && $verified eq $metadata->{version}
    50	            or die "postinstall verification failed\n";
    51	        -x $app->{executable} && -r $app->{desktop}
    52	            or die "postinstall payload validation failed\n";
    53	        $event->emit('updated', $app->{name}, $installed // 'missing', $metadata->{version});
    54	        return 0;
    55	    };
    56	    my $error = $@;
    57	    return ($error =~ /downgrade/i ? 1 : 1, $error =~ /downgrade/i ? 'downgrade' : 'validation');
    58	}
