    60	sub run_updater {
    61	    my ($self, @argv) = @_;
    62	    @argv <= 1 && (!@argv || $argv[0] eq '--repair-only') or die "usage: managed-external-software-update [--repair-only]\n";
    63	    $> == 0 or die "this updater must run as root\n";
    64	    open my $arch_fh, '-|', '/usr/bin/dpkg', '--print-architecture'
    65	        or die "dpkg is unavailable\n";
    66	    my $architecture = <$arch_fh> // q{};
    67	    close $arch_fh or die "dpkg architecture query failed\n";
    68	    chomp $architecture;
    69	    $architecture eq 'amd64' or die "managed external software updates are supported only on amd64\n";
    70	    my $state = ExternalSoftware::Servicing::State->new();
    71	    $state->prepare();
    72	    my $lock = $state->lock();
    73	    if (!defined $lock) {
    74	        $self->_log('info', 'another managed external software update is already running');
    75	        return 0;
    76	    }
    77	    my $work = $state->work_dir();
    78	    my $event = ExternalSoftware::Servicing::Event->new(directory => $state->event_dir());
    79	    my $http = ExternalSoftware::Servicing::HTTP->new();
    80	    my $repository = ExternalSoftware::Servicing::Repository->new(directory => $state->deb_dir());
    81	    my $deb = ExternalSoftware::Servicing::Deb->new(repository => $repository);
    82	    my @deb_specs = (
    83	        { name => 'bitwarden', label => 'Bitwarden Desktop', url => 'https://bitwarden.com/download/?app=desktop&platform=linux&variant=deb', maximum => 314_572_800, hosts => [qw(bitwarden.com github.com objects.githubusercontent.com release-assets.githubusercontent.com)], packages => ['bitwarden'], executable => '/opt/Bitwarden/bitwarden', desktop => '/usr/share/applications/bitwarden.desktop', library => '/opt/Bitwarden/libffmpeg.so' },
    84	        { name => 'obsidian', label => 'Obsidian', packages => ['obsidian'], executable => '/opt/Obsidian/obsidian', desktop => '/usr/share/applications/obsidian.desktop', library => '/opt/Obsidian/libffmpeg.so' },
    85	        { name => 'zoom', label => 'Zoom Workplace', url => 'https://zoom.us/client/latest/zoom_amd64.deb', maximum => 536_870_912, hosts => [qw(zoom.us cdn.zoom.us)], packages => ['zoom'], executable => '/usr/bin/zoom', desktop => '/usr/share/applications/Zoom.desktop', library => q{} },
    86	        { name => 'filen', label => 'Filen Desktop', url => 'https://cdn.filen.io/@filen/desktop/release/latest/Filen_linux_amd64.deb', maximum => 536_870_912, hosts => [qw(cdn.filen.io filen.io)], packages => [qw(filen filen-desktop)], executable => '/opt/Filen/Filen', desktop => '/usr/share/applications/Filen.desktop', library => '/opt/Filen/libffmpeg.so' },
    87	        { name => 'discord', label => 'Discord', url => 'https://discord.com/api/download?platform=linux&format=deb', maximum => 536_870_912, hosts => [qw(discord.com discordapp.com discordapp.net stable.dl2.discordapp.net)], packages => ['discord'], executable => '/usr/bin/discord', desktop => '/usr/share/applications/discord.desktop', library => q{} },
    88	    );
    89	    my ($updated, $failed) = (0, 0);
    90	    eval {
    91	        my $repair_failed = 0;
    92	        for my $spec (@deb_specs) {
    93	            $repair_failed = 1 if !$repository->repair($deb, $spec);
    94	        }
    95	        if (@argv && $argv[0] eq '--repair-only') {
    96	            $self->_log(
    97	                $repair_failed ? 'warning' : 'info',
    98	                $repair_failed
    99	                    ? 'one or more managed Debian packages could not be repaired offline'
   100	                    : 'managed Debian package offline repair completed',
   101	            );
   102	            $state->cleanup_work_dir($work);
   103	            return $repair_failed ? 1 : 0;
   104	        }
   105	        $event->emit('checking', 'all', '-', '-');
   106	        for my $app (grep { $_->{name} ne 'obsidian' } @deb_specs) {
   107	            my ($result, $reason) = $self->_deb_update($http, $deb, $event, $work, $app);
   108	            $updated++ if $result == 0;
   109	            if ($result == 1) { $failed++; $event->emit('failed', $app->{name}, $reason, '-'); }
   110	        }
   111	        my ($obsidian_result, $obsidian_reason) =
   112	            ExternalSoftware::Servicing::Obsidian->new(http => $http, deb => $deb, event => $event)->update($work);
   113	        if ($obsidian_result == 0) {
   114	            $updated++;
   115	        } elsif ($obsidian_result == 1) {
   116	            $failed++;
   117	            $event->emit('failed', 'obsidian', $obsidian_reason, '-');
   118	        }
   119	        my ($tuta_result, $tuta_reason) = ExternalSoftware::Servicing::Tuta->new(http => $http, event => $event, state => $state)->update($work);
   120	        if ($tuta_result == 0) {
   121	            $updated++;
   122	        } elsif ($tuta_result == 1) {
   123	            $failed++;
   124	            $event->emit('failed', 'tuta', $tuta_reason, '-');
   125	        }
   126	        my ($ledger_result, $ledger_reason) = ExternalSoftware::Servicing::Ledger->new(http => $http, event => $event, state => $state)->update($work);
   127	        if ($ledger_result == 0) {
   128	            $updated++;
   129	        } elsif ($ledger_result == 1) {
   130	            $failed++;
   131	            $event->emit('failed', 'ledger', $ledger_reason, '-');
   132	        }
   133	        $event->emit($updated || $failed ? 'complete' : 'no-updates', 'all', $updated || 0, $failed || 0);
   134	        1;
   135	    };
   136	    my $error = $@;
   137	    $state->cleanup_work_dir($work);
   138	    die $error if $error;
   139	    return $failed ? 1 : 0;
   140	}
