     3	
     4	runtime_log_canonical() {
     5	  case "${1:-error}" in
     6	    debug|DEBUG) printf '%s\n' debug ;;
     7	    info|INFO) printf '%s\n' info ;;
     8	    warn|WARN|warning|WARNING) printf '%s\n' warning ;;
     9	    error|ERROR|fatal|FATAL) printf '%s\n' error ;;
    10	    none|NONE) printf '%s\n' none ;;
    11	    *) return 1 ;;
    12	  esac
    13	}
    14	
    15	runtime_log_level_value() {
    16	  case "$1" in
    17	    debug) printf '%s\n' 10 ;;
    18	    info) printf '%s\n' 20 ;;
    19	    warning) printf '%s\n' 30 ;;
    20	    error) printf '%s\n' 40 ;;
    21	    none) printf '%s\n' 99 ;;
    22	    *) return 1 ;;
    23	  esac
    24	}
    25	
    26	runtime_log_raw_error() {
    27	  printf 'error: %s\n' "$*" >&2
    28	}
    29	
    30	runtime_log_init() {
    31	  RUNTIME_LOG_TAG=$1
    32	  RUNTIME_LOG_LEVEL_VAR=$2
    33	  RUNTIME_LOG_DEFAULT_LEVEL=${3:-error}
    34	
    35	  case "$RUNTIME_LOG_LEVEL_VAR" in
    36	    ''|[!ABCDEFGHIJKLMNOPQRSTUVWXYZ_]*|*[!ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_]*)
    37	      runtime_log_raw_error "invalid log level variable name: ${RUNTIME_LOG_LEVEL_VAR:-unset}"
    38	      exit 1
    39	      ;;
    40	    *)
    41	      ;;
    42	  esac
    43	
    44	  # shellcheck disable=SC2086,SC2154
    45	  eval "runtime_log_raw_level=\${$RUNTIME_LOG_LEVEL_VAR-}"
    46	  [ -n "$runtime_log_raw_level" ] || runtime_log_raw_level=$RUNTIME_LOG_DEFAULT_LEVEL
    47	  RUNTIME_LOG_ACTIVE_LEVEL=$(runtime_log_canonical "$runtime_log_raw_level") || {
    48	    runtime_log_raw_error "${RUNTIME_LOG_LEVEL_VAR} must be debug, info, warning, error, or none"
    49	    exit 1
    50	  }
    51	  RUNTIME_LOG_ACTIVE_VALUE=$(runtime_log_level_value "$RUNTIME_LOG_ACTIVE_LEVEL") || exit 1
    52	  RUNTIME_LOGGER=
    53	  RUNTIME_LOGGER_READY=0
    54	}
    55	
    56	runtime_log_should_emit() {
    57	  runtime_requested_level=$(runtime_log_canonical "$1") || runtime_requested_level=error
