const r = await tools.exec_command({cmd:"set -eu
profiles=$(rg -l '^NFTABLES_LOG_LEVEL=' d-i/forky/hosts/profiles | sort)
awk -F= '
/^(NFTABLES_LOG_LEVEL|ZRAM_LOG_LEVEL|SYSTEMD_LOG_LEVEL)=/ { vals[$1]=$2 }
END { print "reference:"; for (k in vals) print k "=" vals[k] }
' d-i/forky/hosts/profiles/btrfs/desktop.env
printf 'profiles_with_all_three='; count=0; for f in $profiles; do n=$(rg -c '^(NFTABLES_LOG_LEVEL|ZRAM_LOG_LEVEL|SYSTEMD_LOG_LEVEL)=' "$f"); [ "$n" -eq 3 ] || { echo "bad:$f:$n" >&2; exit 1; }; count=$((count+1)); done; echo "$count"
for v in NFTABLES_LOG_LEVEL ZRAM_LOG_LEVEL SYSTEMD_LOG_LEVEL; do printf '%s distinct_values=' "$v"; rg "^${v}=" d-i/forky/hosts/profiles | sed 's/.*=//' | sort -u | tr '\n' ' '; echo; done
printf '%s\n' 'load order verified from lib.sh: profile, identity, runtime, [server], layout, layout-family, boot'","workdir":"/home/mcramer/Workspace/debian-preseed-di-new","yield_time_ms":10000,"max_output_tokens":10000});
